.mode list
.headers off
SELECT '--M1 coverage: vols,docs,front,ednote', COUNT(DISTINCT volume_id), COUNT(*), SUM(is_front_matter), SUM(is_editorial_note) FROM document_cache;
SELECT '--M1 nonapp denominator', COUNT(*) FROM document_cache WHERE is_front_matter=0 AND is_editorial_note=0;
SELECT '--M1 nonapp denominator without Ed2', COUNT(*) FROM document_cache WHERE is_front_matter=0 AND is_editorial_note=0 AND volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2');
WITH h AS (SELECT DISTINCT c.volume_id v, c.document_id d FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH 'corrupt* OR briberi OR bribe*' AND c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2')) SELECT '--M2 set h docs, vols', COUNT(*), COUNT(DISTINCT v) FROM h;
SELECT '--M2 total volumes', COUNT(DISTINCT volume_id) FROM document_cache;
WITH h AS (SELECT DISTINCT c.volume_id v, c.document_id d FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH 'corrupt* OR briberi OR bribe*' AND c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2')) SELECT '--M9 citation_era', s.citation_era, COUNT(*) FROM h JOIN document_sources s ON s.volume_id=h.v AND s.document_id=h.d GROUP BY 2 ORDER BY 3 DESC;
WITH h AS (SELECT DISTINCT c.volume_id v, c.document_id d FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH 'corrupt* OR briberi OR bribe*' AND c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2')) SELECT '--M9 decimal by repo/RG', coalesce(s.repository,'(none)'), coalesce(s.record_group,'-'), COUNT(*) FROM h JOIN document_sources s ON s.volume_id=h.v AND s.document_id=h.d WHERE s.citation_era='decimal' GROUP BY 2,3 ORDER BY 4 DESC;
WITH h AS (SELECT DISTINCT c.volume_id v, c.document_id d FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH 'corrupt* OR briberi OR bribe*' AND c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2')) SELECT '--M9 no document_sources row', COUNT(*) FROM h LEFT JOIN document_sources s ON s.volume_id=h.v AND s.document_id=h.d WHERE s.volume_id IS NULL;
WITH h AS (SELECT DISTINCT c.volume_id v, c.document_id d FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH 'corrupt* OR briberi OR bribe*' AND c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2')) SELECT '--M9 decimal_class', s.decimal_class, COUNT(*) FROM h JOIN document_sources s ON s.volume_id=h.v AND s.document_id=h.d WHERE s.citation_era='decimal' GROUP BY 2 ORDER BY 3 DESC LIMIT 6;
WITH h AS (SELECT DISTINCT c.volume_id v, c.document_id d FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH 'corrupt* OR briberi OR bribe*' AND c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2')) SELECT '--M10 anchor rows/docs', e.anchor, COUNT(*), COUNT(DISTINCT e.volume_id||'/'||e.document_id) FROM h JOIN external_citations e ON e.volume_id=h.v AND e.document_id=h.d GROUP BY 2;
WITH h AS (SELECT DISTINCT c.volume_id v, c.document_id d FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH 'corrupt* OR briberi OR bribe*' AND c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2')) SELECT '--M10 pointed-at decimal class', e.decimal_class, COUNT(DISTINCT e.volume_id||'/'||e.document_id), MIN(dd.date_iso), MAX(dd.date_iso) FROM h JOIN external_citations e ON e.volume_id=h.v AND e.document_id=h.d LEFT JOIN document_dates dd ON dd.volume_id=h.v AND dd.document_id=h.d WHERE e.decimal_class IN ('795B.00','751G.00') GROUP BY 2;
WITH h AS (SELECT DISTINCT c.volume_id v, c.document_id d FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH 'corrupt* OR briberi OR bribe*' AND c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2')) SELECT '--M10 pointed-at top', e.anchor, coalesce(e.repository,''), coalesce(e.collection,''), coalesce(e.lot_file_norm,''), COUNT(DISTINCT e.volume_id||'/'||e.document_id) n FROM h JOIN external_citations e ON e.volume_id=h.v AND e.document_id=h.d GROUP BY 2,3,4,5 ORDER BY n DESC LIMIT 12;
WITH h AS (SELECT DISTINCT c.volume_id v, c.document_id d FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH 'corrupt* OR briberi OR bribe*' AND c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2')) SELECT '--M9 came-from top', coalesce(s.repository,''), coalesce(s.record_group,''), coalesce(s.series_name,''), coalesce(s.lot_file_norm,''), COUNT(*) n FROM h JOIN document_sources s ON s.volume_id=h.v AND s.document_id=h.d GROUP BY 2,3,4,5 ORDER BY n DESC LIMIT 14;
SELECT '--M4 fcpa docs,vols', COUNT(*), COUNT(DISTINCT c.volume_id) FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH '"foreign corrupt practices"' AND c.is_front_matter=0 AND c.is_editorial_note=0;
SELECT '--M4 illicit docs,vols', COUNT(*), COUNT(DISTINCT c.volume_id) FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH '"illicit payments"' AND c.is_front_matter=0 AND c.is_editorial_note=0;
SELECT '--M4 qp docs,vols', COUNT(*), COUNT(DISTINCT c.volume_id) FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH '"questionable payments"' AND c.is_front_matter=0 AND c.is_editorial_note=0;
SELECT '--M4 klepto', COUNT(*) FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH 'kleptocra*' AND c.is_front_matter=0 AND c.is_editorial_note=0;
SELECT '--M4 dept of state docs,vols', COUNT(*), COUNT(DISTINCT c.volume_id) FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH '"department of state"' AND c.is_front_matter=0 AND c.is_editorial_note=0;
SELECT '--M4 corrupt* docs,vols', COUNT(*), COUNT(DISTINCT c.volume_id) FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH 'corrupt*' AND c.is_front_matter=0 AND c.is_editorial_note=0;
SELECT '--M4 bribe docs,vols', COUNT(*), COUNT(DISTINCT c.volume_id) FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH 'briberi OR bribe*' AND c.is_front_matter=0 AND c.is_editorial_note=0;
